<?php
/**
 * SVG Icons class
 *
 * @package Themes_Harbor_SVG_Icons
 */

/**
 * This class is in charge of displaying SVG icons across the site.
 *
 * All icons are assumed to have equal width and height, hence the option
 * to only specify a `$size` parameter in the svg methods.
 *
 * @since 1.0.0
 */
class Themes_Harbor_SVG_Icons {

	/**
	 * Gets the SVG code for a given icon.
	 *
	 * @param string $group The icon group.
	 * @param string $icon The icon.
	 * @param int    $size The icon-size in pixels.
	 * @return string
	 */
	public static function get_svg( $group, $icon, $size ) {
		if ( 'ui' === $group ) {
			$arr = self::$ui_icons;
		} elseif ( 'social' === $group ) {
			$arr = self::$social_icons;
		} else {
			$arr = array();
		}

		if ( array_key_exists( $icon, $arr ) ) {
			$repl = sprintf( '<svg class="svg-icon th-fill-current" width="%d" height="%d" aria-hidden="true" role="img" focusable="false" ', $size, $size );
			$svg  = preg_replace( '/^<svg /', $repl, trim( $arr[ $icon ] ) ); // Add extra attributes to SVG code.
			$svg  = preg_replace( "/([\n\t]+)/", ' ', $svg ); // Remove newlines & tabs.
			$svg  = preg_replace( '/>\s*</', '><', $svg ); // Remove white space between SVG tags.
			return $svg;
		}

		return null;
	}

	/**
	 * Detects the social network from a URL and returns the SVG code for its icon.
	 *
	 * @param string $uri Social link.
	 * @param int    $size The icon-size in pixels.
	 * @return string
	 */
	public static function get_social_link_svg( $uri, $size ) {
		static $regex_map; // Only compute regex map once, for performance.

		if ( ! isset( $regex_map ) ) {
			$regex_map = array();
			$map = &self::$social_icons_map; // Use reference instead of copy, to save memory.

			foreach ( array_keys( self::$social_icons ) as $icon ) {
				$domains = array_key_exists( $icon, $map ) ? $map[ $icon ] : array( sprintf( '%s.com', $icon ) );
				$domains = array_map( 'trim', $domains ); // Remove leading/trailing spaces, to prevent regex from failing to match.
				$domains = array_map( 'preg_quote', $domains );
				$regex_map[ $icon ] = sprintf( '/(%s)/i', implode( '|', $domains ) );
			}
		}

		foreach ( $regex_map as $icon => $regex ) {
			if ( preg_match( $regex, $uri ) ) {
				// Display a proper icon for the Google Maps.
				if ( in_array( $icon, array( 'google', 'goo' ), true ) && strpos( $uri, '/maps/' ) ) {
					$icon = 'mappin';
				}

				return self::get_svg( 'social', $icon, $size );
			}
		}

		return null;
	}

